using GraphApi.Models.USR.Marcas;namespace GraphApi.Services.USR.Marcas{    /// <summary>    /// Define las operaciones de negocio y persistencia para Marcas.    /// </summary>    public interface IMarcasService    {        /// <summary>        /// Obtiene la lista de Marcas con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadMarcas>> GetMarcas(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de Marcas con filtros opcionales.        /// </summary>        /// <param name="marcaID">Filtro opcional para MarcaID.</param>        /// <param name="marca">Filtro opcional para Marca.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetMarcasDynamic(            int? marcaID,            string? marca,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo Marca.        /// </summary>        /// <param name="objInput">Datos para crear el Marca.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadMarcas> CreateMarcas(            clCreateMarcas objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un Marca.        /// </summary>        /// <param name="objInput">Datos para actualizar el Marca, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadMarcas?> UpdateMarcas(            clUpdateMarcas objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un Marca por su ID.        /// </summary>        /// <param name="nMarcasID">ID del Marca a eliminar.</param>        Task<bool> DeleteMarcas(int nMarcasID);    }}